// ═══════════════════════════════════════════════════════════════
// EXTRAER DATOS BÁSICOS - EVOLUTION API (v2)
// ═══════════════════════════════════════════════════════════════

const input = $input.first().json;
const body = input.body || input;

// FILTRO CRÍTICO: Solo procesar mensajes reales (messages.upsert)
// Esto ignora: SEND_MESSAGE (eco del bot), CONNECTION_UPDATE, etc.
const event = body.event || '';
if (event !== 'messages.upsert') {
    return [{ json: { skip: true, reason: 'Evento ignorado: ' + event } }];
}

const payloadData = body.data || body;

// Dependiendo del evento, data puede tener ya el key/message, o tenerlos dentro de data.message
const msgObj = payloadData.message && payloadData.message.key ? payloadData.message : payloadData;

const key = msgObj.key || {};
const message = msgObj.message || {};

// ═══════════════════════════════════════════════════════════════
// FILTRO ANTI-LOOP ROBUSTO: Verificar multiples ubicaciones de fromMe
// Evolution API v2 puede poner fromMe en diferentes lugares
// ═══════════════════════════════════════════════════════════════
const isFromMe = key.fromMe === true || 
                 payloadData.fromMe === true || 
                 msgObj.fromMe === true ||
                 (key.fromMe !== undefined && key.fromMe !== false);

if (isFromMe) {
    return [{ json: { skip: true, reason: 'Mensaje propio (fromMe)' } }];
}

// Filtro adicional: si status es 2 (mensaje enviado por nosotros)
if (msgObj.status === 2 || payloadData.status === 2) {
    return [{ json: { skip: true, reason: 'Mensaje con status=2 (enviado)' } }];
}

let targetJid = key.remoteJid || '';

// Filtrar mensajes de status/broadcast
if (targetJid === 'status@broadcast' || targetJid.endsWith('@g.us')) {
    return [{ json: { skip: true, reason: 'Mensaje de status o grupo ignorado' } }];
}

let phoneRaw = targetJid.replace('@s.whatsapp.net', '').replace(/\\D/g, '');
if (phoneRaw.length === 10) phoneRaw = '52' + phoneRaw;

let textContent = '';
if (message.conversation) textContent = message.conversation;
else if (message.extendedTextMessage?.text) textContent = message.extendedTextMessage.text;
else if (message.imageMessage?.caption) textContent = message.imageMessage.caption;
else return [{ json: { skip: true, reason: 'Tipo de mensaje no texto' } }];

// Filtro final: ignorar mensajes vacios
if (!textContent || textContent.trim() === '') {
    return [{ json: { skip: true, reason: 'Mensaje vacio' } }];
}

return [{
  json: {
    phone_number: phoneRaw,
    message_body: textContent,
    message_id: key.id || '',
    remote_jid: targetJid,
    from_me: false,
    user_name: msgObj.pushName || payloadData.pushName || body.pushName || 'Cliente',
    instance_name: body.instance || 'HunabkuBot',
    channel: 'evolution'
  }
}];

// EXTRAER DATOS - META WHATSAPP API
// Laravel ya pre-extrae los datos del payload de Meta

const input = $input.first().json;
const body = input.body || input;

const phoneNumber = body.phone_number || '';
const messageText = body.message_body || '';
const contactName = body.user_name || 'Cliente';
const messageId = body.message_id || '';
const channel = body.channel || 'meta';

if (!phoneNumber || !messageText) {
    return [{ json: { skip: true, reason: 'Mensaje Meta incompleto' } }];
}

let phoneRaw = phoneNumber.replace(/\D/g, '');
if (phoneRaw.length === 10) phoneRaw = '52' + phoneRaw;

return [{
  json: {
    phone_number: phoneRaw,
    message_body: messageText,
    message_id: messageId,
    remote_jid: phoneNumber,
    from_me: false,
    user_name: contactName,
    instance_name: 'MetaAPI',
    channel: channel
  }
}];

// Obtener datos del mensaje (viene de Procesar?)
const inputData = $('Procesar?').first().json;
const historyArray = inputData.history || [];

// Obtener contexto de la base de conocimiento
const kbData = $('Obtener Contexto').first().json;
const knowledgeContext = kbData.context || '';

// Usar horario Mexico/Guadalajara (UTC-6)
const now = new Date();
const mexicoOffset = -6;
const mexicoTime = new Date(now.getTime() + (mexicoOffset * 60 * 60 * 1000) + (now.getTimezoneOffset() * 60 * 1000));
const dateStr = mexicoTime.toISOString().split('T')[0];
const timeStr = mexicoTime.toTimeString().split(' ')[0].substring(0,5);
const dayNames = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];
const dayName = dayNames[mexicoTime.getDay()];

// Generar mapa explicito de dias de la semana con sus fechas
let dayDateMap = '';
for (let i = 0; i < 7; i++) {
    const d = new Date(mexicoTime.getTime() + (i * 24 * 60 * 60 * 1000));
    const dName = dayNames[d.getDay()];
    const dDate = d.toISOString().split('T')[0];
    const label = i === 0 ? '(hoy)' : i === 1 ? '(manana)' : '';
    dayDateMap += `- ${dName} ${label}: ${dDate}\n`;
}

const systemMessage = {
    role: 'system',
    content: `Eres un asistente conversacional de WhatsApp. Eres un asistente profesional, formal y muy educado. SIEMPRE debes tratar al usuario de "usted". No uses jerga ni lenguaje coloquial.

INFORMACION DE CONTEXTO (Base de Conocimiento):
${knowledgeContext}

REGLAS IMPORTANTES DE CONVERSACION:
- Utiliza un tono profesional, respetuoso y formal en todo momento. Dirigete al usuario de "usted".
- TUS MENSAJES DEBEN SER MUY CORTOS Y CONCISOS. Maximo 2 oraciones por respuesta. Debes sonar como un humano atendiendo por WhatsApp, no como un robot escribiendo ensayos.
- NUNCA repitas el mismo saludo. Si ya saludaste antes en el historial, NO vuelvas a saludar.
- Si el usuario pregunta "que haces" o "en que puedes ayudar", responde de manera breve y profesional: puedes agendar citas y responder preguntas.
- Lee el historial de la conversacion y responde de forma coherente con lo que ya se dijo.
- Ve directo al punto. No des explicaciones largas a menos que te lo pidan.
- Varia tus respuestas, no uses siempre las mismas frases.

CAPACIDADES DE CITAS:
- Puedes agendar, cancelar y reagendar citas para los clientes
- El horario de atencion es configurable (por defecto 9:00 a 17:00, lunes a viernes)
- Solo se permite UNA cita activa por cliente
- Al agendar, SIEMPRE pide el correo electronico del cliente para enviarle un recordatorio por email

FECHA Y HORA ACTUAL:
- Fecha: ${dateStr}
- Hora: ${timeStr}
- Dia: ${dayName}

CALENDARIO DE ESTA SEMANA (usa estas fechas exactas, NO calcules tu):
${dayDateMap}
INSTRUCCIONES PARA CITAS:
Cuando detectes que el cliente quiere agendar, cancelar, reagendar o consultar disponibilidad, responde UNICAMENTE con un JSON en este formato exacto (sin texto adicional, sin markdown, sin backticks):

Para AGENDAR una cita (IMPORTANTE: necesitas nombre, fecha, hora Y email):
{"action":"appointment_create","date":"YYYY-MM-DD","time":"HH:MM","name":"nombre del cliente","email":"correo@ejemplo.com"}

Para CANCELAR una cita:
{"action":"appointment_cancel"}

Para REAGENDAR una cita:
{"action":"appointment_reschedule","date":"YYYY-MM-DD","time":"HH:MM"}

Para CONSULTAR DISPONIBILIDAD de un dia especifico:
{"action":"appointment_available","date":"YYYY-MM-DD"}

Para VER PROXIMOS HORARIOS DISPONIBLES (cuando no dicen fecha):
{"action":"appointment_next_available"}

REGLAS CRITICAS (MUY IMPORTANTE):
1. SOLO responde con JSON cuando el usuario EXPLICITAMENTE pida una accion de citas
2. Mensajes como "hola", "puedes ayudarme?", "tengo cita?" son preguntas NORMALES, responde con TEXTO plano
3. NUNCA asumas ni inventes fechas u horas. Si el usuario pide agendar pero NO especifica el dia o la hora exacta, NO USES EL JSON. Responde con texto plano preguntandole a que hora y que dia le gustaria la cita.
4. SOLO usa appointment_cancel cuando digan EXPLICITAMENTE: "cancela mi cita", "quiero cancelar", "no quiero la cita"
5. NUNCA canceles una cita si solo PREGUNTAN sobre su cita
6. Cuando digan "manana", "el lunes", USA EL CALENDARIO DE ARRIBA
7. Si preguntan "que dias tienes disponibles", usa appointment_next_available
8. Para agendar, SIEMPRE pregunta el nombre completo del cliente. NO uses el nombre de contacto de WhatsApp directamente, pregunta: como te llamas? o a nombre de quien sera la cita?\n9. Para agendar, SIEMPRE pregunta tambien por el correo electronico del cliente. El email es necesario para enviarles un recordatorio por email. Necesitas nombre, fecha, hora Y email antes de generar el JSON de appointment_create.

CONTEXTO ACTUAL:
- Estas hablando con: ${inputData.user_name} (Tel: ${inputData.phone}).`
};

let groqMessages = [systemMessage];

if (Array.isArray(historyArray)) {
    for (const msg of historyArray) {
        groqMessages.push({
            role: msg.role === 'user' ? 'user' : 'assistant',
            content: msg.content
        });
    }
}

return [{ json: { groqMessages, phone: inputData.phone, userName: inputData.user_name, remoteJid: inputData.remote_jid, instanceName: inputData.instance_name || 'HunabkuBot', channel: inputData.channel || 'evolution' } }];

const groqResponse = $input.first().json;
const content = groqResponse.choices?.[0]?.message?.content || '';

let actionData = null;
try {
    const jsonMatch = content.match(/\{[\s\S]*"action"[\s\S]*\}/);
    if (jsonMatch) {
        actionData = JSON.parse(jsonMatch[0]);
    }
} catch(e) {}

const phone = $('Formatear para AI').item.json.phone || '';
const userName = $('Formatear para AI').item.json.userName || 'Cliente';
const remoteJid = $('Formatear para AI').item.json.remoteJid || '';
const instanceName = $('Formatear para AI').item.json.instanceName || 'HunabkuBot';
const channel = $('Formatear para AI').item.json.channel || 'evolution';
const tokensUsed = groqResponse.usage?.total_tokens || 0;

if (actionData && actionData.action) {
    // Remap appointment_next_available to appointment_available (sin date)
    let action = actionData.action;
    if (action === 'appointment_next_available') {
        action = 'appointment_available';
    }
    if (action === 'appointment_create' && (!actionData.date || !actionData.time)) {
        return [{ json: { isAction: false, text: '¡Claro! Por favor dime qué día y a qué hora te gustaría tu cita.', phone, userName, remoteJid, instanceName, channel, tokensUsed, originalContent: content } }];
    }
    if (action === 'appointment_create' && !actionData.email) {
        return [{ json: { isAction: false, text: '¡Casi listo! Solo necesito tu correo electrónico para enviarte un recordatorio de la cita. 📧', phone, userName, remoteJid, instanceName, channel, tokensUsed, originalContent: content } }];
    }
    if (action === 'appointment_reschedule' && (!actionData.date || !actionData.time)) {
        return [{ json: { isAction: false, text: '¡Claro! Por favor dime la nueva fecha y hora para reagendar tu cita.', phone, userName, remoteJid, instanceName, channel, tokensUsed, originalContent: content } }];
    }

    return [{
        json: {
            isAction: true,
            action: action,
            date: actionData.date || null,
            time: actionData.time || null,
            name: actionData.name || userName,
            email: actionData.email || null,
            phone, userName, remoteJid, instanceName, channel, tokensUsed,
            originalContent: content
        }
    }];
} else {
    return [{
        json: {
            isAction: false,
            text: content,
            phone, userName, remoteJid, instanceName, channel, tokensUsed
        }
    }];
}

// Detectar de qué nodo viene el resultado principal (Crear, Cancelar o Reagendar)
let result = {};
try { result = $('Crear Cita').item.json; } catch(e) {}
try { if (!result.success) result = $('Cancelar Cita').item.json; } catch(e) {}
try { if (!result.success) result = $('Reagendar Cita').item.json; } catch(e) {}
try { if (!result.success) result = $('Consultar Disponibilidad').item.json; } catch(e) {}
try { if (!result.success) result = $('Consultar Proximos').item.json; } catch(e) {}

// Si fallaron las alternativas, usa el input crudo (por si hay un error)
if (Object.keys(result).length === 0) {
    result = $input.first().json;
}

const actionNode = $('Detectar Accion');
const action = actionNode.first().json.action;
const phone = actionNode.first().json.phone;
const remoteJid = actionNode.first().json.remoteJid;
const instanceName = actionNode.first().json.instanceName;
const channel = actionNode.first().json.channel;
const tokensUsed = actionNode.first().json.tokensUsed;
let message = '';

if (result.success) {
    switch(action) {
        case 'appointment_create':
            message = `✅ ¡Cita agendada!\n📅 ${result.data.scheduled_at}`;
            if (result.data.meet_link) message += `\n📹 Google Meet: ${result.data.meet_link}`;
            message += '\n\nSi necesitas cancelar o reagendar, solo escribeme.';
            break;
        case 'appointment_cancel':
            message = `❌ Tu cita ha sido cancelada.\n📅 Era para: ${result.data.scheduled_at}\n\nSi quieres agendar una nueva, solo avisame.`;
            break;
        case 'appointment_reschedule':
            message = `🔄 ¡Cita reagendada!\n📅 Nueva fecha: ${result.data.scheduled_at}`;
            if (result.data.meet_link) message += `\n📹 Google Meet: ${result.data.meet_link}`;
            break;
        case 'appointment_available':
            if (result.data && result.data.days && result.data.days.length > 0) {
                message = '📅 Proximos horarios disponibles:\n';
                for (const day of result.data.days) {
                    const slotsPreview = day.available_slots.slice(0, 6).join(', ');
                    const more = day.available_slots.length > 6 ? ` y ${day.available_slots.length - 6} mas` : '';
                    message += `\n📌 ${day.day_name} ${day.date_display}: ${slotsPreview}${more}`;
                }
                message += '\n\n¿Que dia y hora te conviene?';
            } else if (result.data && result.data.total_available > 0) {
                message = ` Horarios disponibles para el ${result.data.date} (${result.data.day_name}):\n\n`;
                message += result.data.available_slots.join(', ');
                message += '\n\n¿A que hora te gustaria tu cita?';
            } else {
                message = '😕 No hay horarios disponibles para esa fecha.\n¿Quieres probar otro dia?';
            }
            break;
        default:
            message = result.message || 'Solicitud procesada.';
    }
} else {
    // Extraer error si viene envuelto por n8n en result.error.description
    let errorMsg = result.message;
    if (result.error && typeof result.error.description === 'string') {
        try {
            const parsed = JSON.parse(result.error.description);
            errorMsg = parsed.message || result.error.message;
        } catch(e) {
            errorMsg = result.error.description || result.error.message;
        }
    }
    message = errorMsg || 'Hubo un problema procesando tu solicitud. Por favor intenta de nuevo con otro horario o formato.';
}

return [{ json: { text: message, phone, remoteJid, instanceName, channel, tokensUsed } }];

